// secret-shield: masks secrets before Claude reads them, in tool results, in the
// prompts you send, in what Claude Code attaches for Claude, such as an
// @-mentioned file or CLAUDE.md, and in every row the conversation stores. It
// sends nothing and keeps nothing past the session. It shows where it masked
// what (kinds, names, lines, never values) in a transcript line and in /shield,
// and opens /shield by itself the first time a place holds a secret it
// shouldn't (⚠): source code, a log, a web page, CLAUDE.md.
//
// When a check fails, the content is withheld rather than passed on unchecked.
// Showing where something was masked never decides that: its failure is ignored.

import { atom, read, update } from 'claude-code'
import { MARKER, maskText, maskValue, total, describe } from './redact.js'

const WITHHELD = 'secret-shield could not check this output for secrets, so it was withheld. Tell the user; do not retry the same call.'
const PANE = 'shield'
const OPEN = { id: PANE, title: 'secret-shield', focus: true, closeOnEscape: true, rows: 14 }

// What was masked this session, newest last: { where, warn, spots }
const masked = atom({ plugin: 'secret-shield', key: 'masked' }, [])

// Files whose job is to hold secrets, so one found there is expected. An example
// or template copy is meant to be committed, so one found there gets ⚠.
const SECRET_FILE = /(?:^|[/\\])(?:\.env(?!\.(?:example|sample|template|dist)$)(?:\.[\w-]+)?|\.dev\.vars|\.npmrc|\.pypirc|\.netrc|\.pgpass|\.git-credentials|credentials(?:\.[\w-]+)?|secrets?(?:\.[\w-]+)?|id_(?:rsa|dsa|ecdsa|ed25519)|[\w.-]+\.(?:pem|key|p12|pfx|jks|keystore))$/i
// MCP tools that hand out a secret by design, such as Neon's get_connection_string
const SECRET_TOOL = /credential|connection_string|secret|token|password|api_?key/i

// Whether a secret is expected where a tool call found it
function expected(e, spot) {
  if (spot.file) return SECRET_FILE.test(spot.file)
  const path = e.file_path ?? e.notebook_path ?? e.path
  if (path) return SECRET_FILE.test(path)
  if (e.tool === 'Bash') return /^\s*(?:env|printenv)\b/.test(e.command) || e.command.split(/[\s;|&<>'"=]+/).some((word) => SECRET_FILE.test(word))
  return e.tool.startsWith('mcp__') && SECRET_TOOL.test(e.tool)
}

const oneLine = (text) => {
  const line = String(text).replace(/\s+/g, ' ').trim()
  return line.length > 70 ? line.slice(0, 69) + '…' : line
}

// Where a tool's output came from, in one line; a long path keeps its end, the
// file's name, and a command is masked as well
function where(e) {
  const path = e.file_path ?? e.notebook_path
  if (path) return e.tool + ' ' + (path.length > 60 ? '…' + path.slice(-59) : path)
  const detail = e.url ?? (typeof e.command === 'string' ? maskText(e.command, {}) : e.pattern !== undefined ? e.pattern + (e.path ? ' ' + e.path : '') : '')
  return oneLine(e.tool + ' ' + detail)
}

// One hit as a line: 第 3 行  ECPAY_HASH_KEY  env-secret
const spotText = (spot) => [spot.file ? spot.file + ':' + spot.fileLine : '第 ' + spot.line + ' 行', spot.name, spot.kind].filter(Boolean).join('  ')

// Put a place last in the session's list, once; true when it needs a look and hadn't yet
async function remember($, place, spots, warn) {
  const isNew = warn && !(await read($, masked)).some((one) => one.warn && one.where === place)
  await update($, masked, (list) => [...list.filter((one) => one.where !== place), { where: place, warn, spots: spots.slice(0, 20) }].slice(-100))
  return isNew
}

// A transcript line, the session's list, and the list opened the first time a place needs a look
async function report($, hits, place, spots, warn) {
  $.ui.log((warn ? '⚠ ' : '') + '已遮蔽 ' + describe(hits) + '（' + place + '）' + (warn ? '，/shield 看位置' : ''))
  if (!(await remember($, place, spots, warn))) return
  // Opened unasked, a narrow terminal waits to draw it, so say where to look. A
  // toast is a small box under the mod's name: keep it short, the place is in the line above
  const opened = await $.ui.open(OPEN)
  if (!opened.isPlaced) $.ui.toast('⚠ 密鑰出現在不該有的地方，輸入 /shield 查看')
}

const quietly = (work) => work.catch(() => undefined)

async function shieldToolCall($, e, next) {
  // A mask written back into a file would replace the real secret
  if (JSON.stringify(e).includes(MARKER)) {
    return { deny: 'This call contains a secret-shield mask (' + MARKER + '...]]). Running it would overwrite the real secret with the mask. Leave the lines that hold secrets unchanged, or ask the user to edit them.' }
  }
  const out = await next(e)
  const hits = {}
  const spots = []

  // A refusal or an error reaches Claude as text, so mask that text
  if (out.deny !== undefined || out.isError) {
    const text = maskText(out.deny ?? out.text ?? String(out.result ?? ''), hits, spots)
    if (total(hits) === 0) return out
    await quietly(report($, hits, where(e) + ' 的錯誤訊息', spots, spots.some((spot) => !expected(e, spot))))
    return { deny: text }
  }

  const result = maskValue(out.result, hits, spots)
  const context = out.context?.map((c) => maskText(c, hits, spots))
  if (total(hits) === 0) return out
  // A read from line 40 counts its lines from there
  const startLine = e.tool === 'Read' ? out.result?.file?.startLine ?? 1 : 1
  for (const spot of spots) spot.line += startLine - 1
  await quietly(report($, hits, where(e), spots, spots.some((spot) => !expected(e, spot))))
  // Without core's ref, Claude Code maps the masked record for Claude afresh
  return context ? { result, context } : { result }
}

async function shieldPrompt($, e, next) {
  const hits = {}
  const spots = []
  const text = maskText(e.text, hits, spots)
  const context = e.context?.map((c) => maskText(c, hits, spots))
  if (total(hits) === 0) return next(e)
  $.ui.toast('secret-shield：你的訊息裡有 ' + describe(hits) + '，已遮蔽後才送出')
  await quietly(remember($, '你的訊息', spots, false))
  return next(context ? { ...e, text, context } : { ...e, text })
}

async function shieldAttachment($, e, next) {
  const hits = {}
  const spots = []
  const text = maskText(e.text, hits, spots)
  if (total(hits) === 0) return next(e)
  // A file you @-mentioned is the engine's; a settings hook's or plugin's text has no business holding one
  await quietly(report($, hits, '附加內容 ' + e.type, spots, e.origin?.kind !== 'engine'))
  return next({ ...e, text })
}

async function shieldContext($, e, next) {
  const hits = {}
  const spots = []
  const blocks = e.blocks.map((b) => ({ ...b, text: maskText(b.text, hits, spots) }))
  if (total(hits) === 0) return next(e)
  await quietly(report($, hits, '開場內容，例如 CLAUDE.md', spots, true))
  // The rewritten CLAUDE.md text no longer matches the file list, so leave the list out
  const { instructionFiles, ...rest } = e
  return next({ ...rest, blocks })
}

// The last check: every row the conversation keeps, before it's stored and sent.
// It catches what the hooks above don't see, such as a skill's text or a hook's
// added context. Claude's own replies are left out, since Claude can't repeat a
// secret it never received.
const ROW_DOORS = ['prompt', 'command', 'tool-result', 'tool-message', 'delivery', 'attachment', 'hook-context', 'note', 'compaction', 'notice']

async function shieldRow($, e, next) {
  const hits = {}
  const spots = []
  const content = maskValue(e.message.content, hits, spots)
  if (total(hits) === 0) return next(e)
  await quietly(report($, hits, '對話紀錄 ' + e.door, spots, true))
  return next({ ...e, message: { ...e.message, content } })
}

// A row's text replaced by a notice, keeping each tool result's block so the
// conversation still pairs every tool call with a result
const WITHHELD_ROW = '[secret-shield withheld this content because it could not be checked for secrets]'
function withhold(content) {
  return content.map((block) => {
    if (block.type === 'text') return { ...block, text: WITHHELD_ROW }
    if (block.type === 'tool_result') return { ...block, content: [{ type: 'text', text: WITHHELD_ROW }] }
    return block
  })
}

// The session's list, newest first, ⚠ places in amber; values are never in it
async function drawList($, e) {
  const { Box, Text } = $.ui.resolve(e)
  const list = await read($, masked)
  const lines = []
  for (const one of [...list].reverse()) {
    lines.push(h(Text, one.warn ? { color: '#fbbf24', bold: true } : {}, (one.warn ? '⚠ ' : '  ') + one.where))
    for (const spot of one.spots.slice(0, 5)) lines.push(h(Text, one.warn ? {} : { dimColor: true }, '    ' + spotText(spot)))
    if (one.spots.length > 5) lines.push(h(Text, { dimColor: true }, '    …還有 ' + (one.spots.length - 5) + ' 個'))
  }
  const warns = list.filter((one) => one.warn).length
  return h(
    Box,
    { flexDirection: 'column' },
    h(Text, { bold: true }, list.length ? '這個 session 遮蔽了 ' + list.length + ' 處' + (warns ? '，' + warns + ' 處要注意' : '') + '（不顯示值）' : '這個 session 還沒有遮蔽任何東西'),
    h(Text, { dimColor: true }, '⚠ = 密鑰出現在不該有的地方：原始碼、log、網頁、MCP 回應、CLAUDE.md'),
    ...lines.slice(0, 80),
    h(Text, { dimColor: true }, 'Esc 關閉 · /shield 再打開'),
  )
}

export function register(on) {
  on('tool.call', shieldToolCall).catch(async ($, e, next) => {
    return { deny: WITHHELD + ' (' + next.error.kind + ')' }
  })

  on('prompt.submit', shieldPrompt).catch(async ($, e, next) => {
    // Once the prompt was passed on, it went in masked; otherwise keep it from going in
    return next.called ? next(e) : { drop: 'secret-shield 無法檢查這則訊息，所以沒有送出。' }
  })

  on('prompt.attachment', shieldAttachment).catch(async () => {
    return { text: null }
  })

  on('prompt.context', shieldContext).catch(async ($, e, next) => {
    // Send the conversation without the blocks that couldn't be checked
    return { blocks: e.blocks.filter((b) => b.name === 'currentDate') }
  })

  on('session.append', { door: ROW_DOORS }, shieldRow).catch(async ($, e, next) => {
    // Once the row was passed on, it went in masked; otherwise store it withheld
    return next.called ? next(e) : next({ ...e, message: { ...e.message, content: withhold(e.message.content) } })
  })

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'shield', description: '這個 session 遮蔽了什麼、在哪裡（不顯示值）' })
    return next(e)
  })

  on('command.run', { command: 'shield' }, async ($) => {
    const list = await read($, masked)
    await $.ui.open(OPEN)
    const warns = list.filter((one) => one.warn).length
    return { text: list.length ? '這個 session 遮蔽了 ' + list.length + ' 處' + (warns ? '，' + warns + ' 處要注意（⚠）' : '') : '這個 session 還沒有遮蔽任何東西' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, drawList)

  // A 🛡 after the spinner's word while Claude works shows the shield is running.
  // If it's missing, this mod didn't load and nothing is being masked.
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    return next({ ...e, props: { ...e.props, suffix: (e.props.suffix ?? '') + ' 🛡' } })
  })
}

