// Finds secrets in text and replaces each with a mask such as [[redacted:github-token]].
// Pure functions with no mods API calls, so tests can run them directly.

// Every mask starts with this, so a call that would write a mask back into a file
// can be recognized. Built from two parts so this file never contains it whole,
// which would make edits to this file look like a mask being written back.
export const MARKER = '[[' + 'redacted:'
const mask = (kind) => MARKER + kind + ']]'

// Name parts that mark a value as a secret, such as API_KEY, hashKey, or clientSecret.
// The lookahead stops at the end of the word, so "tokenizer" doesn't count.
const NAME = '(?:secret[_-]?key|secret|token|passw(?:or)?d|pwd|api[_-]?key|apikey|hash[_-]?key|hash[_-]?iv|private[_-]?key|access[_-]?key|auth[_-]?key|credentials?)s?(?![a-z])'
const ENV_NAME = '(?:SECRET_?KEY|SECRET|TOKEN|PASSW(?:OR)?D|PWD|API_?KEY|APIKEY|HASH_?KEY|HASH_?IV|PRIVATE_?KEY|ACCESS_?KEY|AUTH_?KEY|CREDENTIALS?)S?(?![A-Za-z])'

// A value that says where a secret lives, rather than being the secret
const REFERENCE = /^\$|\$\{|process\.env|os\.environ|getenv|\[\[redacted:/
// A value that is clearly a placeholder, a type, or a setting rather than a secret
const NOT_SECRET = /^(?:x+|\*+|\.+|<[^>]*>|your[-_ ].*|changeme|change[-_]me|example.*|dummy.*|placeholder.*|null|none|nil|undefined|true|false|string|number|required|optional|\d+|https?:\/\/.*)$/i

const isSecret = (v) => !REFERENCE.test(v) && !NOT_SECRET.test(v)
// Code such as settings.API_KEY or getKey() on the right of an assignment
const isCode = (v) => /^[A-Za-z_]\w*(?:\.\w+)+$/.test(v) || /[()[\]{}]/.test(v)

// Each rule's regex names the secret part (?<secret>); the text around it is kept.
// Quantifiers on names are bounded so long runs of letters can't make a rule slow.
const RULES = [
  // A PEM private key, through its END line, or to the end of text that was cut off
  { kind: 'private-key', re: /(?<secret>-----BEGIN [A-Z0-9 ]{0,40}PRIVATE KEY-----(?:[\s\S]*?-----END [A-Z0-9 ]{0,40}PRIVATE KEY-----|[\s\S]*$))/g },

  // Tokens with a recognizable prefix
  { kind: 'anthropic-key', re: /(?<secret>\bsk-ant-[A-Za-z0-9_-]{20,})/g },
  { kind: 'openai-key', re: /(?<secret>\bsk-(?:proj-|svcacct-|admin-)?[A-Za-z0-9_-]{20,})/g },
  { kind: 'stripe-key', re: /(?<secret>\b(?:sk|rk)_(?:live|test)_[A-Za-z0-9]{16,})/g },
  { kind: 'stripe-webhook-secret', re: /(?<secret>\bwhsec_[A-Za-z0-9+/=]{20,})/g },
  { kind: 'github-token', re: /(?<secret>\b(?:gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{30,}))/g },
  { kind: 'gitlab-token', re: /(?<secret>\bglpat-[A-Za-z0-9_-]{20,})/g },
  { kind: 'slack-token', re: /(?<secret>\bxox[abposr]-[A-Za-z0-9-]{10,})/g },
  { kind: 'slack-webhook', re: /(?<before>https:\/\/hooks\.slack\.com\/services\/)(?<secret>[A-Za-z0-9_/-]{20,})/g },
  { kind: 'aws-access-key-id', re: /(?<secret>\b(?:AKIA|ASIA)[0-9A-Z]{16}\b)/g },
  { kind: 'google-api-key', re: /(?<secret>\bAIza[0-9A-Za-z_-]{35})/g },
  { kind: 'npm-token', re: /(?<secret>\bnpm_[A-Za-z0-9]{36})/g },
  { kind: 'neon-api-key', re: /(?<secret>\bnapi_[A-Za-z0-9]{30,})/g },
  { kind: 'notion-token', re: /(?<secret>\b(?:secret_|ntn_)[A-Za-z0-9]{40,})/g },
  { kind: 'clickup-token', re: /(?<secret>\bpk_\d{3,}_[A-Z0-9]{20,})/g },
  { kind: 'jwt', re: /(?<secret>\beyJ[A-Za-z0-9_-]{8,}\.eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,})/g },
  { kind: 'bearer-token', re: /(?<before>\b(?:Bearer|Basic)[ \t]+)(?<secret>[A-Za-z0-9._~+/=-]{16,})/g },

  // The password in a URL such as postgres://user:REDACTED@host
  { kind: 'url-password', re: /(?<before>\b[a-z][a-z0-9+.-]{1,20}:\/\/[^\s:/?#@]{1,100}:)(?<secret>[^\s@/]{3,200})(?=@)/gi, check: isSecret },

  // An environment-style line: API_KEY=..., export DB_PASSWORD="...", - POSTGRES_PASSWORD: ...
  { kind: 'env-secret', re: new RegExp('(?<before>^[ \\t]*(?:export[ \\t]+|-[ \\t]*)?[A-Z0-9_]{0,40}' + ENV_NAME + '[A-Z0-9_]{0,40}[ \\t]*[=:][ \\t]*)(?<q>["\']?)(?<secret>[^\\s"\'#]{4,})\\k<q>', 'gm'), check: (v) => isSecret(v) && !isCode(v) },

  // A quoted value given to a secret-looking name: "HashKey": "...", $apiKey = '...', token: `...`
  { kind: 'secret-value', re: new RegExp('(?<before>[\\w$.-]{0,40}' + NAME + '[\\w.-]{0,40}["\'`]?[ \\t]*(?::=|=>|:|=)[ \\t]*)(?<q>["\'`])(?<secret>[^"\'`\\s]{6,})\\k<q>', 'gi'), check: isSecret },

  // An unquoted YAML or INI value with letters and digits: password: hunter2abc
  { kind: 'secret-value', re: new RegExp('(?<before>^[ \\t]*-?[ \\t]*[\\w.-]{0,40}' + NAME + '[\\w.-]{0,40}[ \\t]*[:=][ \\t]*)(?<secret>[^\\s"\'#,;{}()[\\]]{8,})(?=[ \\t]*$)', 'gim'), check: (v) => isSecret(v) && /\d/.test(v) && /[A-Za-z]/.test(v) },
]

// Mask every secret in a string, adding one to hits[kind] for each. Given an
// array `found`, also add where each one was (see locate), never its value.
export function maskText(text, hits, found) {
  let out = text
  // Masks hold no line breaks, so only a private key block, masked first, takes
  // lines away: each fold says after which line and how many, so later hits
  // still get their line in the text as given
  const folds = []
  for (const rule of RULES) {
    let from = 0
    let line = 1
    const pass = []
    out = out.replace(rule.re, (...args) => {
      const groups = args[args.length - 1]
      if (rule.check && !rule.check(groups.secret)) return args[0]
      hits[rule.kind] = (hits[rule.kind] ?? 0) + 1
      if (found) {
        const offset = args[args.length - 3]
        const src = args[args.length - 2]
        line += breaks(src, from, offset)
        from = offset
        const shift = folds.reduce((n, fold) => n + (fold.line < line ? fold.lost : 0), 0)
        found.push(locate(rule.kind, groups.before, src, offset, line + shift))
        const lost = breaks(args[0], 0, args[0].length)
        if (lost) pass.push({ line: line - pass.reduce((n, fold) => n + fold.lost, 0), lost })
      }
      const q = groups.q ?? ''
      return (groups.before ?? '') + q + mask(rule.kind) + q
    })
    folds.push(...pass)
  }
  return out
}

function breaks(text, from, to) {
  let n = 0
  for (let i = text.indexOf('\n', from); i !== -1 && i < to; i = text.indexOf('\n', i + 1)) n++
  return n
}

// Where a hit was: its kind and line, the name it was given on its line
// (API_KEY=, "HashKey": , postgres://app:), and for grep-style output
// (src/pay.ts:12:...) the file and line
function locate(kind, before, text, offset, line) {
  const spot = { kind, line }
  const start = text.lastIndexOf('\n', offset - 1) + 1
  const lead = text.slice(Math.max(start, offset - 300), offset) + (before ?? '')
  const name = /([\w$.-]+(?::\/\/[\w.-]+)?)["'`]?\s*(?::=|=>|[:=])\s*["'`]?$/.exec(lead)?.[1]
  if (name) spot.name = name.slice(-60)
  const grep = /^([^\s:]*[./][^\s:]*):(\d+)[:-]/.exec(text.slice(start, start + 300))
  if (grep) {
    spot.file = grep[1]
    spot.fileLine = Number(grep[2])
  }
  return spot
}

// Binary content, such as an image's bytes, sits in these fields and is left alone
function isBinaryField(obj, key) {
  return key === 'base64' || (key === 'data' && ('media_type' in obj || 'mimeType' in obj || obj.type === 'base64'))
}

// Mask every string inside a value, keeping its shape so the tool's schema still fits
export function maskValue(value, hits, found) {
  if (typeof value === 'string') return maskText(value, hits, found)
  if (Array.isArray(value)) return value.map((item) => maskValue(item, hits, found))
  if (value && typeof value === 'object') {
    const out = {}
    for (const [key, item] of Object.entries(value)) {
      out[key] = typeof item === 'string' && isBinaryField(value, key) ? item : maskValue(item, hits, found)
    }
    return out
  }
  return value
}

export const total = (hits) => Object.values(hits).reduce((sum, n) => sum + n, 0)

// A summary that names the kinds and counts, never the values
export const describe = (hits) => Object.entries(hits).map(([kind, n]) => n + ' 個 ' + kind).join('、')

