// What /shield lists, held in $.state for the session: where, never the value

// One hit: its kind and line, the name it was given, and for grep-style output the file and line it names
export type Spot = { kind: string; line: number; name?: string; file?: string; fileLine?: number }

// One place something was masked; warn when a secret has no business being there (⚠)
export type Masked = { where: string; warn: boolean; spots: Spot[] }

declare module 'claude-code' {
  interface PluginState {
    'secret-shield': { masked: Masked[] }
  }
}
